config.prelude:
static int lock_depth;
static int lock_enter_count;
static int lock_exit_count;
static int lock_balance_errors;

void test_reset_lock_stats(void) {
    lock_depth = 0;
    lock_enter_count = 0;
    lock_exit_count = 0;
    lock_balance_errors = 0;
}

void enter_critical(void) {
    lock_enter_count++;
    if (lock_depth != 0) {
        lock_balance_errors++;
    }
    lock_depth++;
}

void exit_critical(void) {
    lock_exit_count++;
    if (lock_depth != 1) {
        lock_balance_errors++;
    }
    if (lock_depth > 0) {
        lock_depth--;
    }
}

int test_lock_enters(void) { return lock_enter_count; }
int test_lock_exits(void) { return lock_exit_count; }
int test_lock_depth(void) { return lock_depth; }
int test_lock_errors(void) { return lock_balance_errors; }

visibleCases.displayInput:
irq_ring_t rb;
irq_ring_init(&rb);
test_reset_lock_stats();
size_t size = irq_ring_size(&rb);

irq_ring_t rb;
irq_ring_init(&rb);
test_reset_lock_stats();
bool a = irq_ring_push_isr(&rb, 0x11);
bool b = irq_ring_push_isr(&rb, 0x22);
uint8_t out1 = 0;
uint8_t out2 = 0;
bool p1 = irq_ring_pop(&rb, &out1);
bool p2 = irq_ring_pop(&rb, &out2);

irq_ring_t rb;
irq_ring_init(&rb);
bool ok = true;
for (uint8_t i = 0; i < IRQ_RING_CAPACITY; i++) {
    ok = ok && irq_ring_push_isr(&rb, (uint8_t)(i + 1));
}
bool overflow = irq_ring_push_isr(&rb, 99);
test_reset_lock_stats();
size_t size = irq_ring_size(&rb);

irq_ring_t rb;
irq_ring_init(&rb);
for (int i = 0; i < 6; i++) {
    irq_ring_push_isr(&rb, i);
}
uint8_t drop = 0;
irq_ring_pop(&rb, &drop);
irq_ring_pop(&rb, &drop);
irq_ring_pop(&rb, &drop);
irq_ring_push_isr(&rb, 100);
irq_ring_push_isr(&rb, 101);
irq_ring_push_isr(&rb, 102);
uint8_t popped[6];
for (int i = 0; i < 6; i++) {
    irq_ring_pop(&rb, &popped[i]);
}
